      baseRenderClientLeadsV65(a,s);
      if(a?.leadsHasMore)$('view').insertAdjacentHTML('beforeend','<div class="dialog-actions" style="justify-content:center;margin-top:18px"><button class="secondary" data-action="lead-more" type="button">Показать более ранние заявки</button></div>');
