      const scanIcon='<svg viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><circle cx="20" cy="20" r="16" stroke="currentColor" stroke-opacity=".18" stroke-width="3"/><path d="M20 4a16 16 0 0 1 16 16" stroke="currentColor" stroke-width="3" stroke-linecap="round"/><circle cx="20" cy="20" r="4.5" fill="currentColor"/></svg>';
      const playIcon='<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M8 5v14l11-7Z"/></svg>';
