      const sevLabel={high:'Критично',medium:'Важно',low:'Незначительно'},sevTone={high:'bad',medium:'warn',low:'neutral'};
      const allIssues=diagnosticsRan?(editorInventory.diagnostics.issues||[]).filter(item=>item.category!=='availability'):[];
      const issueActionCell=(issue,index)=>issue.page?'<a class="ghost" href="'+h(issue.page)+'" target="_blank" rel="noopener noreferrer">Открыть страницу</a>':'<button class="ghost" type="button" data-action="issue-detail" data-issue="'+index+'">Показать</button>';
      const issuesTable=allIssues.length?'<div class="table-wrap"><table><thead><tr><th>Проблема</th><th>Раздел</th><th>Приоритет</th><th>Действие</th></tr></thead><tbody>'+allIssues.map((issue,index)=>'<tr><td>'+h(issue.title)+'</td><td>'+h(CATEGORY_LABELS[issue.category]||issue.category)+'</td><td><span class="pill '+(sevTone[issue.severity]||'neutral')+'">'+h(sevLabel[issue.severity]||issue.severity)+'</span></td><td>'+issueActionCell(issue,index)+'</td></tr>').join('')+'</tbody></table></div>':diagnosticsRan?'<div class="all-clear"><i>✓</i><span>Проблем не найдено</span></div>':empty('Запустите диагностику, чтобы увидеть список проблем.');
