    async function applyEditorProposal(button){
      const p=editorProposal;if(!p||p.type!=='change')return;
      const candidateId=p.kind.startsWith('button_')?(document.querySelector('input[name="editorCandidate"]:checked')?.value||p.selectedCandidateId||''):'';
      const phoneCandidateId=p.kind==='phone'?(p.selectedCandidateId||''):'';
      if(p.kind.startsWith('button_')&&!candidateId){toast('Выберите конкретную кнопку.');return}
      const scope=p.scope||p.manualScope||$('changeScope')?.value||'element';
      try{
        busy(button,true);
        const result=await api('/v1/platform/sites/'+encodeURIComponent(siteId)+'/changes/apply',{method:'POST',body:JSON.stringify({kind:p.kind,value:p.value,candidateId,phoneCandidateId,scope,targetPhone:p.targetPhone||''})});
        const s=site();const refreshed=await Promise.all([api('/v1/platform/sites/'+encodeURIComponent(siteId)+'/overrides'),operatorPreviewAccountId?Promise.resolve(null):api('/v1/platform/sites/'+encodeURIComponent(siteId)+'/conversation')]);s._overrides=refreshed[0];if(refreshed[1])s._conversation=refreshed[1].conversation;editorProposal=null;try{sessionStorage.removeItem('sitecare:draft:'+siteId)}catch{}render();toast(result.message);void watchAppliedChange(result.version,p.kind,siteId)
      }
      catch(err){toast(err.message)}finally{busy(button,false)}
    }

    async function watchAppliedChange(version,kind,watchedSiteId){
      for(let attempt=0;attempt<8;attempt+=1){
        await new Promise(resolve=>setTimeout(resolve,1600));
        if(siteId!==watchedSiteId)return;
        try{
          const next=await api('/v1/platform/sites/'+encodeURIComponent(watchedSiteId)+'/overrides');
          const selected=site();if(!selected||selected.site_id!==watchedSiteId)return;selected._overrides=next;
          if(currentView==='client-overview')render();
          const change=(next.changes||[]).find(item=>Number(item.version)===Number(version));
          if(change?.status==='confirmed'){toast(kind==='phone'?'Готово — номер изменён на сайте.':'Готово — изменение применено на сайте.');return}
          if(change?.status==='not_found'&&attempt>=2){toast('Не удалось применить изменение. Предыдущую версию можно вернуть в истории.');return}
        }catch{return}
      }
      toast('Изменение сохранено, но сайт ещё не подтвердил результат. Откройте опубликованную страницу и обновите её.');
    }

    async function injectQuickAnswer(userText,aiText){
      const s=site();if(!s)return;
      if(!s._conversation)s._conversation={messages:[],supportRequest:null};
      const now=new Date().toISOString();
      s._conversation.messages=[...(s._conversation.messages||[]),{role:'client',content:userText,createdAt:now},{role:'ai',content:aiText,createdAt:now}];
      s._conversation.updatedAt=now;
      render();
      // Quick actions answer instantly without the /assistant round trip, but
      // that means this exchange only exists in local state until it's saved
      // here -- without this, the next real message overwrites s._conversation
      // with the server's snapshot and this exchange visibly disappears.
      try{
        const result=await api('/v1/platform/sites/'+encodeURIComponent(siteId)+'/conversation/quick',{method:'POST',body:JSON.stringify({userText,aiText})});
        const selected=site();if(selected&&selected.site_id===s.site_id)selected._conversation=result.conversation;
      }catch{}
    }
    async function handleQuickAction(kind,button){
      const s=site();if(!s)return;
      try{
        busy(button,true);
        if(kind==='quick-check'){
          const result=await api('/v1/platform/sites/'+encodeURIComponent(siteId)+'/check',{method:'POST',body:'{}'});
          s.page_ok=result.pageOk?1:0;
          s.tls_ok=result.tlsOk?1:0;
          if(result.loaderOk!==null&&result.loaderOk!==undefined)s.loader_ok=result.loaderOk?1:0;
          const webhookReady=!Number(s.form_required)||(Boolean(s.webhook_verified_at)&&Boolean(s.form_verified_at));
          const lines=[
            (result.pageOk?'✓':'!')+' Сайт '+(result.pageOk?'открывается':'сейчас не открывается'),
            (webhookReady?'✓':'!')+' '+(webhookReady?'Заявки подключены':'Приём заявок ещё не настроен'),
            (s.telegram_enabled?'✓':'!')+' Telegram '+(s.telegram_enabled?'подключён':'не подключён')
          ];
          injectQuickAnswer('Проверь состояние сайта','Проверил сайт — вот что нашёл:\\n\\n'+lines.join('\\n'));
          return;
        }
        if(kind==='quick-capability'||kind==='quick-handoff'){
          const prompt=kind==='quick-capability'?'Что ты умеешь?':'Позови специалиста поддержки';
          const result=await api('/v1/platform/sites/'+encodeURIComponent(siteId)+'/assistant',{method:'POST',body:JSON.stringify({prompt})});
          s._conversation=result.conversation;
          editorProposal=result.type==='support'?null:{...result,siteId,selectedCandidateId:result.suggestedCandidateId||''};
          render();
          return;
        }
        const inv=await api('/v1/platform/sites/'+encodeURIComponent(siteId)+'/inventory');
        if(kind==='quick-seo'){
          const issues=(inv.diagnostics?.issues||[]).filter(item=>item.category==='seo');
          const word=issues.length===1?'замечание':issues.length<5?'замечания':'замечаний';
          const text=issues.length?('Нашёл '+issues.length+' SEO-'+word+', которые стоит поправить:\\n\\n'+issues.slice(0,6).map(item=>'• '+item.title).join('\\n')+'\\n\\nМогу разобрать любой пункт подробнее — просто спросите.'):'SEO-замечаний не найдено — с этой стороны сайт в порядке.';
          injectQuickAnswer('Проведи SEO-диагностику',text);
        }else if(kind==='quick-improve'){
          const issues=inv.diagnostics?.issues||[];
          const word=issues.length===1?'замечание':issues.length<5?'замечания':'замечаний';
          const text=issues.length?('Нашёл '+issues.length+' '+word+', которые стоит поправить:\\n\\n'+issues.slice(0,6).map(item=>'• '+item.title).join('\\n')+'\\n\\nМогу разобрать любой пункт подробнее — просто спросите.'):'Критических замечаний не нашёл — сайт в порядке.';
          injectQuickAnswer('Что можно улучшить?',text);
        }else if(kind==='quick-leads'){
          const webhookReady=!Number(s.form_required)||(Boolean(s.webhook_verified_at)&&Boolean(s.form_verified_at));
          const text=webhookReady?'Приём заявок подключён и подтверждён — технических причин для сбоя не вижу.\\n\\nЕсли заявки всё равно не приходят, проверьте:\\n• форма опубликована на сайте\\n• адрес формы не менялся недавно':(Number(s.form_required)?'Приём заявок ещё не подтверждён — нужно проверить Webhook формы в настройках подключения.':'На подключённой странице пока не найдена обязательная форма заявки.');
          injectQuickAnswer('Почему могут не приходить заявки?',text);
        }
      }catch(err){toast(err.message)}finally{busy(button,false)}
    }
    async function handleEditorAction(action,button){
      if(action.startsWith('quick-'))return handleQuickAction(action,button);
      if(action==='prepare')return prepareEditorChange(button);
      if(action==='reply-choice'){const field=$('changePromptV45');if(!field)return;field.value=button.dataset.reply||'';field.dispatchEvent(new Event('input',{bubbles:true}));return prepareEditorChange(button)}
      if(action==='select-on-site')return openSiteSelector(button.dataset.selectKind||'phone');
      if(action==='chat-widget-close'){chatWidgetOpen=false;renderChatWidget();return}
      if(action==='chat-widget-expand'){chatWidgetExpanded=!chatWidgetExpanded;renderChatWidget();return}
      if(action==='support-request')return requestEditorSupport(button);
      if(action==='support-dismiss'){editorProposal=null;render();return}
      if(action==='support-cancel')return cancelEditorSupport(button);
      if(action==='proposal-close'){editorProposal=null;render();return}
      if(action==='apply')return applyEditorProposal(button);
    }

    function navigate(view){if(!view||view===currentView)return;currentView=view==='client-edit'?'client-overview':view;if(view!=='operator-clients')operatorClientId='';render();window.scrollTo({top:0,behavior:'smooth'})}
    async function load(preferred=accountId){const data=await api('/v1/platform/dashboard'+(preferred?'?account='+encodeURIComponent(preferred):''));state=data;csrf=data.csrf;accountId=data.selected_account_id||data.accounts[0]?.account_id||'';const a=account(),requestedSite=initialParams.get('site')||'';if(requestedSite&&a?.sites.some(x=>x.site_id===requestedSite))siteId=requestedSite;else if(!siteId||!a?.sites.some(x=>x.site_id===siteId))siteId=a?.sites[0]?.site_id||'';const operator=data.user.platform_role==='operator',requestedView=initialParams.get('view')||'';if(!currentView||currentView.startsWith(operator?'client-':'operator-'))currentView=operator?(requestedView==='support'?'operator-support':'operator-overview'):'client-home';$('panelVersion').classList.toggle('hidden',!operator);$('profileName').textContent=data.user.display_name;$('profileEmail').textContent=data.user.email;$('profileAvatar').textContent=initials(data.user.display_name);$('loginScreen').classList.add('hidden');$('app').classList.remove('hidden');render()}
    async function checkSite(button,targetSite=siteId){try{busy(button,true);const result=await api('/v1/platform/sites/'+encodeURIComponent(targetSite)+'/check',{method:'POST',body:'{}'});if(!result.pageOk)toast('Сайт не открылся. Уведомление появится только при повторной ошибке.');else if(result.loaderOk===false)toast('Сайт открывается, но код SiteCare не найден. Опубликуйте страницу и проверьте снова.');else toast('Сайт открывается, код SiteCare найден.');await load(accountId)}catch(err){toast(err.message)}finally{busy(button,false)}}
    async function runDiagnostics(){
      const s=site();if(!s||diagnosticsRunning)return;
      diagnosticsRunning=true;render();
      try{
        const [checkResult,inv]=await Promise.all([
          api('/v1/platform/sites/'+encodeURIComponent(siteId)+'/check',{method:'POST',body:'{}'}),
          api('/v1/platform/sites/'+encodeURIComponent(siteId)+'/inventory')
        ]);
        s.page_ok=checkResult.pageOk?1:0;
        s.tls_ok=checkResult.tlsOk?1:0;
        if(checkResult.loaderOk!==null&&checkResult.loaderOk!==undefined)s.loader_ok=checkResult.loaderOk?1:0;
        editorInventory={...(editorInventory||{}),...inv};
      }catch(err){toast(err.message)}
      finally{diagnosticsRunning=false;render()}
    }
